query OrderScreen($id: ID!) {
  order(id: $id) {
    status
    eta
    rider { name phone }
    items { name qty }
  }
}

type Order {
  id: ID!
  status: OrderStatus!
  eta: DateTime
  restaurant: Restaurant!
  rider: Rider
  items: [OrderItem!]!
}

type Restaurant {
  id: ID!
  name: String!
  menu: [Dish!]!
}

type Query {
  order(id: ID!): Order
  restaurants(near: String!, first: Int, after: String): RestaurantPage!
}

syntax = "proto3";

service Payments {
  rpc ChargeOrder(ChargeRequest) returns (Charge);
  rpc RefundCharge(RefundRequest) returns (Charge);
  rpc WatchCharge(ChargeId) returns (stream ChargeEvent);
}

message ChargeRequest {
  int64 order_id = 1;
  int64 amount_paise = 2;
  string method = 3;          // "upi", "card"
  string idempotency_key = 4;
}

